tasks.solution:
def add(a: int, b: int) -> int:
    """Compute add."""
    return a + b

def subtract(a: int, b: int) -> int:
    """Compute subtract."""
    return a - b

def multiply(a: int, b: int) -> int:
    """Compute multiply."""
    return a * b

def divide(a: int, b: int) -> float:
    """Compute divide."""
    return a / b

def negate(a: int) -> int:
    """Compute negate."""
    return -a

def absolute(a: int) -> int:
    """Compute absolute."""
    return abs(a)

def minimum(a: int, b: int) -> int:
    """Compute minimum."""
    return min(a, b)

def maximum(a: int, b: int) -> int:
    """Compute maximum."""
    return max(a, b)

def clamp(a: int, lo: int, hi: int) -> int:
    """Compute clamp."""
    return min(max(a, lo), hi)

def square(a: int) -> int:
    """Compute square."""
    return a * a
